class Solution {
  bool isValidSudoku(List<List<String>> board) {
    var rows = List.filled(9, 0);
    var cols = List.filled(9, 0);
    var grids = List.filled(9, 0);

    for (int r = 0; r < 9; r++) {
      for (int c = 0; c < 9; c++) {
        if (board[r][c] == ".") continue;

        var idx = int.parse(board[r][c]) - 1;

        if (rows[r] & 1 << idx != 0) return false;
        rows[r] |= 1 << idx;

        if (cols[c] & 1 << idx != 0) return false;
        cols[c] |= 1 << idx;

        if (grids[r ~/ 3 * 3 + c ~/ 3] & 1 << idx != 0) return false;
        grids[r ~/ 3 * 3 + c ~/ 3] |= 1 << idx;
      }
    }

    return true;
  }
}

class Solution {
  int trap(List<int> height) {
    if (height.isEmpty) return 0;

    int l = 0;
    int r = height.length - 1;
    int leftMax = height[l];
    int rightMax = height[r];
    int res = 0;

    while (l < r) {
      if (leftMax < rightMax) {
        l++;
        leftMax = leftMax > height[l] ? leftMax : height[l];
        res += leftMax - height[l];
      } else {
        r--;
        rightMax = rightMax > height[r] ? rightMax : height[r];
        res += rightMax - height[r];
      }
    }
    return res;
  }
}

